.bidsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2330;
    background: linear-gradient(165deg, #f4f1ea 0%, #ece6da 100%);
    border-radius: 18px;
}

.bidsim-container * {
    box-sizing: border-box;
}

.bidsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0e1c3a 0%, #1b2f57 55%, #27406e 100%);
    color: #f5f1e6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(14, 28, 58, 0.32);
    border-bottom: 3px solid #c9a24b;
}

.bidsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: 0.4px;
    color: #ffffff;
}

.bidsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e7cf95;
    background: rgba(201, 162, 75, 0.16);
    border: 1px solid rgba(201, 162, 75, 0.4);
    padding: 5px 14px;
    border-radius: 999px;
}

.bidsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.58;
    color: #d9dce6;
}

.bidsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3b5a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.bidsim-period-counter #currentDay,
.bidsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0e1c3a;
}

.bidsim-round-name {
    background: #1b2f57;
    color: #e7cf95;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.bidsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a4b1e;
    background: #f3e2cf;
    padding: 4px 12px;
    border-radius: 999px;
}

.bidsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.bidsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(14, 28, 58, 0.07);
    border-top: 4px solid #1b2f57;
}

.bidsim-card-win { border-top-color: #1b6f9c; }
.bidsim-card-margin { border-top-color: #1d7a52; }
.bidsim-card-impact { border-top-color: #7a4fb0; }
.bidsim-card-faculty { border-top-color: #c9a24b; }

.bidsim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7185;
}

.bidsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0e1c3a;
}

.bidsim-card-win .bidsim-value { color: #1b6f9c; }
.bidsim-card-margin .bidsim-value { color: #1d7a52; }
.bidsim-card-impact .bidsim-value { color: #7a4fb0; }
.bidsim-card-faculty .bidsim-value { color: #b78d2f; }

.bidsim-sublabel {
    font-size: 0.76rem;
    color: #7c8398;
    line-height: 1.35;
}

.bidsim-margin-fail .bidsim-value { color: #c0392b; }
.bidsim-margin-pass .bidsim-value { color: #1d7a52; }
.bidsim-margin-fail { border-top-color: #c0392b; }

.bidsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0e1c3a;
    color: #f0ead9;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c9a24b;
}

.bidsim-budget-bar #budgetDisplay {
    font-size: 1.08rem;
    letter-spacing: 0.3px;
    color: #e7cf95;
}

.bidsim-budget-over #budgetDisplay {
    color: #f0a3a3;
}

.bidsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a24b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(14, 28, 58, 0.06);
}

.bidsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.bidsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0e1c3a;
    margin-bottom: 6px;
}

.bidsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #36405a;
}

.bidsim-briefing-text strong { color: #1d7a52; }
.bidsim-briefing-text em { color: #8a4b1e; font-style: italic; }

.bidsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(14, 28, 58, 0.07);
}

.bidsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0e1c3a;
    border-bottom: 2px solid #efe8d8;
    padding-bottom: 8px;
}

.bidsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28324b;
    margin: 14px 0 6px;
}

.bidsim-container select,
.bidsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfc3a6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf7f0;
    color: #1b2330;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.bidsim-container select:focus,
.bidsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c9a24b;
    box-shadow: 0 0 0 3px rgba(201, 162, 75, 0.2);
}

.bidsim-container select option {
    background-color: #ffffff;
    color: #1b2330;
}

.bidsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1b6f9c;
}

.bidsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1b2f57;
    margin-top: 4px;
}

.bidsim-range-readout span#targetReadout {
    color: #1b6f9c;
    font-weight: 800;
}

.bidsim-hint {
    font-size: 0.8rem;
    color: #7c8398;
    margin-top: 4px;
    line-height: 1.42;
}

.bidsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.bidsim-container .btn-primary {
    background: linear-gradient(135deg, #1b2f57 0%, #27406e 100%);
    border: none;
    padding: 11px 28px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(27, 47, 87, 0.3);
}

.bidsim-container .btn-primary:hover {
    filter: brightness(1.1);
}

.bidsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cfc3a6;
    color: #6a7185;
}

.bidsim-coach {
    background: #0e1c3a;
    color: #eef0f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(14, 28, 58, 0.24);
    border-left: 4px solid #c9a24b;
}

.bidsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7cf95;
    margin-bottom: 8px;
}

.bidsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.bidsim-coach-body strong { color: #e7cf95; }
.bidsim-coach-body em { color: #f0b58a; font-style: italic; }

.bidsim-history,
.bidsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(14, 28, 58, 0.07);
}

.bidsim-history h3,
.bidsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0e1c3a;
}

.bidsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28324b;
}

.bidsim-container table#usfHistoryTable th {
    background: #f1ecdf;
    color: #0e1c3a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d8c6;
}

.bidsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece1;
}

.bidsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.bidsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .bidsim-container {
        padding: 14px;
    }
    .bidsim-header h1 {
        font-size: 1.7rem;
    }
    .bidsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .bidsim-value {
        font-size: 2rem;
    }
    .bidsim-clock {
        margin-left: 0;
    }
    .bidsim-period-counter {
        font-size: 0.88rem;
    }
    .bidsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .bidsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

