.custombid-cm{background:#ffffff;border:1px solid #dbe0ea;border-radius:12px;padding:22px 24px;margin:18px 0;color:#1a2233;font-family:inherit;box-shadow:0 2px 10px rgba(16,24,44,0.06);}
