(function() {
    'use strict';

    class CustomBidAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Custom Bid`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD, $M).
            this.CAP = 4.2;            // client budget cap, $4.2M
            this.MARGIN_FLOOR = 25;    // contribution-margin floor (%)
            this.RIVAL_BID = 3.4;      // consulting firm expected bid, $M
            this.RIVAL_FINAL = 3.35;   // Round 4 revealed bid, $M
            this.TRIP_COST = 0.0095;   // ~$9,500 per international teaching trip, $M
            this.BASE_COST = 1.55;     // base delivery cost before scope/faculty, $M
            this.START_WIN = 30;       // pre-differentiation baseline (~35% at full premium)
            this.START_IMPACT = 12;
            this.START_FACULTY = 18;

            this.TARGET_COMPOSITE = 68; // top performance tier (best reachable ~73)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    winProb: this.START_WIN,
                    margin: 0,
                    marginSet: false,
                    impact: this.START_IMPACT,
                    faculty: this.START_FACULTY,
                    bidPrice: 0,
                    deliveryCost: this.BASE_COST,
                    walkaway: 0,
                    floorBreached: false,
                    winHistory: [this.START_WIN],
                    impactHistory: [this.START_IMPACT],
                    facultyHistory: [this.START_FACULTY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = a MIDDLING, neutral mix (NOT the textbook-correct play).
                state.decisions = {
                    theme: `relationship`,
                    diff: `faculty`,
                    target: 50,
                    scope: `premium`,
                    price: 3.80,
                    posture: `premium`,
                    facultyModel: `flagship`,
                    impactMethod: `dashboard_only`,
                    trips: 24,
                    pitch: `evidence`,
                    walkaway: 3.40,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const th = document.getElementById(`themeInput`);
                const df = document.getElementById(`diffInput`);
                const tg = document.getElementById(`targetInput`);
                if (th) decisions.theme = th.value;
                if (df) decisions.diff = df.value;
                if (tg) decisions.target = parseInt(tg.value, 10);
                if (!Number.isFinite(decisions.target) || decisions.target < 0 || decisions.target > 100) {
                    warn(`warn_target_range`); return false;
                }
            } else if (round === 2) {
                const sc = document.getElementById(`scopeInput`);
                const pr = document.getElementById(`priceInput`);
                const po = document.getElementById(`postureInput`);
                if (sc) decisions.scope = sc.value;
                if (pr) decisions.price = parseFloat(pr.value);
                if (po) decisions.posture = po.value;
                if (!Number.isFinite(decisions.price)) {
                    warn(`warn_price_invalid`); return false;
                }
                if (decisions.price < 3.0 || decisions.price > this.CAP) {
                    warn(`warn_price_cap`); return false;
                }
            } else if (round === 3) {
                const fm = document.getElementById(`facultyModelInput`);
                const im = document.getElementById(`impactMethodInput`);
                const tr = document.getElementById(`tripsInput`);
                if (fm) decisions.facultyModel = fm.value;
                if (im) decisions.impactMethod = im.value;
                if (tr) decisions.trips = parseInt(tr.value, 10);
                if (!Number.isFinite(decisions.trips) || decisions.trips < 0 || decisions.trips > 40) {
                    warn(`warn_trips_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const wa = document.getElementById(`walkawayInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (wa) decisions.walkaway = parseFloat(wa.value);
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.walkaway) || decisions.walkaway < 2.5 || decisions.walkaway > this.CAP) {
                    warn(`warn_walkaway_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let winDelta = 0, impactDelta = 0, facultyDelta = 0, costDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Decode the RFP & set the win strategy (Common Errors 1 & 5).
                switch (d.theme) {
                    case `impact`: impactDelta += 14; winDelta += 4; coachKey = `coach_r1_impact`; break;
                    case `relationship`: winDelta += 2; impactDelta += 2; coachKey = `coach_r1_relationship`; break;
                    case `price`: winDelta += 6; impactDelta -= 8; facultyDelta -= 4; coachKey = `coach_r1_price`; break;
                    case `scale`: impactDelta -= 4; costDelta += 0.10; coachKey = `coach_r1_scale`; break;
                }
                // The decisive edge: impact measurement is the mandatory requirement (the battleground).
                switch (d.diff) {
                    case `measurement`: impactDelta += 12; winDelta += 3; if (d.theme === `impact`) coachKey = `coach_r1_sharp`; break;
                    case `faculty`: facultyDelta += 10; impactDelta += 3; break;
                    case `brand`: impactDelta -= 6; winDelta -= 2; coachKey = `coach_r1_brand`; break;
                    case `none`: impactDelta -= 10; winDelta -= 6; coachKey = `coach_r1_none`; break;
                }
                // Realistic ambition anchors the price band; over/under-confidence both cost.
                if (d.target >= 40 && d.target <= 65) { winDelta += 5; }
                else if (d.target > 65) { winDelta -= 4; coachKey = `coach_r1_overconfident`; }
                else if (d.target <= 25) { winDelta -= 4; coachKey = `coach_r1_defeatist`; }

                summaryKey = (d.theme === `impact` && d.diff === `measurement`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Scope & price the program (Common Errors 1 & 2).
                ds.bidPrice = d.price;
                switch (d.scope) {
                    case `calibrated`: impactDelta += 10; facultyDelta += 4; costDelta += 0.55; coachKey = `coach_r2_calibrated`; break;
                    case `premium`: impactDelta += 14; facultyDelta += 6; costDelta += 1.15; coachKey = `coach_r2_premium`; break;
                    case `lean`: impactDelta -= 8; facultyDelta -= 4; costDelta += 0.15; coachKey = `coach_r2_lean`; break;
                }
                switch (d.posture) {
                    case `calibrated`: winDelta += 8; break;
                    case `premium`: winDelta -= 2; break;
                    case `defensive`: winDelta += 10; impactDelta -= 4; coachKey = `coach_r2_defensive`; break;
                }
                // Price vs the rival's ~$3.4M: each $0.1M above the rival costs win probability.
                const gap = d.price - this.RIVAL_BID;
                winDelta += Math.round((-gap) * 14);

                summaryKey = (d.scope === `calibrated` && d.posture !== `defensive`) ? `sum_r2_good` :
                    (d.scope === `lean` || d.posture === `defensive` ? `sum_r2_lean` : `sum_r2_rich`);
            } else if (round === 3) {
                // Faculty mix & impact methodology (Common Errors 3 & 4).
                switch (d.facultyModel) {
                    case `blended`: facultyDelta += 28; impactDelta += 8; costDelta += 0.40; coachKey = `coach_r3_blended`; break;
                    case `flagship`: facultyDelta += 14; impactDelta += 4; costDelta += 0.85; coachKey = `coach_r3_flagship`; break;
                    case `adjunct`: facultyDelta -= 8; impactDelta -= 8; costDelta += 0.12; coachKey = `coach_r3_adjunct`; break;
                }
                switch (d.impactMethod) {
                    case `baseline_endline`: impactDelta += 20; winDelta += 6; if (d.facultyModel === `blended`) coachKey = `coach_r3_strong`; break;
                    case `dashboard_only`: impactDelta += 2; winDelta -= 2; coachKey = `coach_r3_dashboard`; break;
                    case `satisfaction`: impactDelta -= 10; winDelta -= 4; coachKey = `coach_r3_satisfaction`; break;
                }
                // International teaching trips: anchor three regions, but airfare burns margin.
                costDelta += d.trips * this.TRIP_COST;
                if (d.trips >= 14 && d.trips <= 26) { facultyDelta += 8; }
                else if (d.trips > 26) { facultyDelta += 4; if (coachKey === `coach_r3_blended`) coachKey = `coach_r3_overtravel`; }
                else if (d.trips < 8) { facultyDelta -= 8; impactDelta -= 4; coachKey = `coach_r3_undertravel`; }

                summaryKey = (d.facultyModel === `blended` && d.impactMethod === `baseline_endline`) ? `sum_r3_good` :
                    (d.facultyModel === `flagship` ? `sum_r3_flagship` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pitch & defend the premium (Common Error 5 + walk-away discipline).
                switch (d.pitch) {
                    case `evidence`: winDelta += 10; impactDelta += 6; coachKey = `coach_r4_evidence`; break;
                    case `assert`: winDelta -= 8; impactDelta -= 4; coachKey = `coach_r4_assert`; break;
                    case `discount`:
                        winDelta += 12;
                        ds.bidPrice = Math.min(ds.bidPrice || this.RIVAL_FINAL, 3.30);
                        coachKey = `coach_r4_discount`;
                        break;
                }
                // Walk-away discipline: a price near the margin floor is disciplined.
                ds.walkaway = d.walkaway;
                if (d.walkaway >= 3.3 && d.walkaway <= 3.75) { winDelta += 4; }
                else if (d.walkaway < 3.0) { winDelta -= 6; coachKey = (d.pitch === `discount`) ? coachKey : `coach_r4_nowalkaway`; }

                winDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.pitch === `evidence` && d.walkaway >= 3.3 && d.walkaway <= 3.75) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.deliveryCost = Math.round((ds.deliveryCost + costDelta) * 1000) / 1000;

            // Margin is derived from the final bid price and accumulated delivery cost.
            if (ds.bidPrice > 0) {
                ds.margin = Math.round(((ds.bidPrice - ds.deliveryCost) / ds.bidPrice) * 100);
                ds.marginSet = true;
                ds.floorBreached = ds.margin < this.MARGIN_FLOOR;
            }

            ds.winProb = Math.max(0, Math.min(100, ds.winProb + winDelta));
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));
            ds.faculty = Math.max(0, Math.min(100, ds.faculty + facultyDelta));

            ds.winHistory.push(Math.round(ds.winProb));
            ds.impactHistory.push(Math.round(ds.impact));
            ds.facultyHistory.push(Math.round(ds.faculty));

            // v1.1.0 fix: persist instructor-card composite every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                winProb: Math.round(ds.winProb),
                winDelta: Math.round(winDelta),
                margin: ds.marginSet ? ds.margin : null,
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                faculty: Math.round(ds.faculty),
                facultyDelta: Math.round(facultyDelta),
                bidPrice: ds.bidPrice,
                floorBreached: ds.floorBreached,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

