        _composite(ds) {
            const winProb = Math.round(ds.winProb);
            const impact = Math.round(ds.impact);
            const faculty = Math.round(ds.faculty);
            const margin = ds.marginSet ? ds.margin : 0;
            const marginScore = Math.max(0, Math.min(40, margin)) / 40 * 100;
            return Math.round(winProb * 0.3 + impact * 0.3 + faculty * 0.2 + marginScore * 0.2);
        }

        _cl(key) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const winProb = Math.round(ds.winProb);
            const impact = Math.round(ds.impact);
            const faculty = Math.round(ds.faculty);
            const margin = ds.marginSet ? ds.margin : 0;
            const meetsFloor = ds.marginSet && margin >= this.MARGIN_FLOOR;

            const marginScore = Math.max(0, Math.min(40, margin)) / 40 * 100;
            const composite = this._composite(ds);

            let performanceKey = `grade_lost`;
            if (meetsFloor && composite >= this.TARGET_COMPOSITE && impact >= 65) performanceKey = `grade_won`;
            else if (meetsFloor && composite >= 55) performanceKey = `grade_credible`;
            else if (!meetsFloor && winProb >= 55) performanceKey = `grade_atloss`;
            else if (meetsFloor && composite >= 42) performanceKey = `grade_thin`;
            else if (composite >= 42) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);
            const met = meetsFloor && composite >= this.TARGET_COMPOSITE && impact >= 65;

            const insights = [];
            if (meetsFloor && composite >= this.TARGET_COMPOSITE && impact >= 65) insights.push(window.mySimulation.t(`insight_won`));
            else if (!meetsFloor) insights.push(window.mySimulation.t(`insight_floor`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (impact < 45) insights.push(window.mySimulation.t(`insight_lowimpact`));
            if (faculty < 45) insights.push(window.mySimulation.t(`insight_lowfaculty`));
            if (ds.bidPrice >= this.CAP - 0.001) insights.push(window.mySimulation.t(`insight_atcap`));
            if (meetsFloor && impact >= 65 && faculty >= 55) insights.push(window.mySimulation.t(`insight_defensible`));

            return {
                winProb: winProb,
                margin: margin,
                impact: impact,
                faculty: faculty,
                meetsFloor: meetsFloor,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="custombid-cm-badge ` + (s.met ? `custombid-cm-met` : `custombid-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (!s.meetsFloor) badges.push(`<span class="custombid-cm-badge custombid-cm-fail">` + t(`cm_fail_floor`) + `</span>`);
            if (s.impact != null && s.impact < 45) badges.push(`<span class="custombid-cm-badge custombid-cm-fail">` + t(`cm_fail_impact`) + `</span>`);
            const kpi = (label, val) => `<div class="custombid-cm-metric"><div class="custombid-cm-metric-val">` + val + `</div><div class="custombid-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_win`), (s.winProb != null ? s.winProb : 0) + `%`) + kpi(t(`cm_impact`), (s.impact != null ? s.impact : 0)) + kpi(t(`cm_faculty`), (s.faculty != null ? s.faculty : 0)) + kpi(t(`cm_margin`), (s.margin != null ? s.margin : 0) + `%`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="custombid-cm">`
                + `<div class="custombid-cm-head"><div class="custombid-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="custombid-cm-scorewrap"><span class="custombid-cm-score">` + score + `</span><span class="custombid-cm-score-max">/100</span></div>`
                + `<div class="custombid-cm-grade">` + grade + `</div>`
                + `<div class="custombid-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="custombid-cm-metrics">` + kpis + `</div>`
                + `<div class="custombid-cm-insights"><div class="custombid-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.marginSet && ds.floorBreached) return window.mySimulation.t(`hint_floor`);
            if (ds.impact < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_impact`);
            if (ds.faculty < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_faculty`);
            if (state.currentPeriod >= 3 && ds.winProb < 35) return window.mySimulation.t(`hint_behind`);
            if (ds.marginSet && !ds.floorBreached && ds.impact >= 65 && ds.winProb >= 50) return window.mySimulation.t(`hint_strong`);
            return null;
